// Source-backed directory. Generated content is kept separate from Prognos-authored guides.
const directoryById=new Map(MEDICAL_DIRECTORY.entries.map(e=>[e.id,e]));
const fold=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const directorySearch=MEDICAL_DIRECTORY.entries.map(e=>({entry:e,title:fold(e.name),aliases:e.aliases.map(fold),text:fold(e.name+' '+e.aliases.join(' ')+' '+(e.searchText||e.excerpt))}));
