function directorySource(s){return `<div class="source"><b>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} · Original information ↗</a>`:`<a href="${esc(s.datasetUrl||'https://rarediseases.info.nih.gov/about')}" target="_blank" rel="noopener">${esc(s.name)} · Original disease list ↗</a>`}</b><br>${esc(s.publisher)}${s.institute?'<br>Primary institute: '+esc(s.institute):''}<br><span class="muted">${esc(s.dataset)} · ${esc(s.datasetDate)}<br>Source review: ${esc(s.reviewed)}${s.published?' · Published: '+esc(s.published):''}${s.recordId?' · '+esc(s.recordId):''}</span></div>`}
function normalizeQuery(q){const n=fold(q);return !['heart','stomach','period'].includes(n)&&aliases[n]?aliases[n]:n}
function directoryResults(q){const nq=normalizeQuery(q),words=nq.split(' ').filter(Boolean);return directorySearch.map(x=>{let score=0;if(!words.length){score=dirState.letter?0:x.entry.kinds.includes('health')?30:x.entry.hasSummary?20:x.entry.sources.some(s=>s.url)?10:0;return {e:x.entry,score}};if(x.title===nq||x.aliases.includes(nq))score=1000;else if(x.title.startsWith(nq))score=800;else if(x.title.includes(nq))score=700;else if(x.aliases.some(a=>a.includes(nq)))score=600;else if(words.every(w=>x.text.includes(w)))score=100;return {e:x.entry,score}}).filter(x=>(!words.length||x.score)&&(!dirState.group||x.e.groups.includes(dirState.group))&&(!dirState.kind||(dirState.kind==='summary'?x.e.hasSummary:x.e.kinds.includes(dirState.kind)))&&(!dirState.letter||(dirState.letter==='#'?/^[0-9]/.test(x.e.name):x.e.name[0].toUpperCase()===dirState.letter))).sort((a,b)=>b.score-a.score||a.e.name.localeCompare(b.e.name)).map(x=>x.e)}
