function dirFilter(key,value){dirState[key]=value;dirState.page=0;render()}
function directoryCard(e){return `<button class="condition directory-card" onclick="dirTab='overview';location.hash='condition/${e.id}'"><span class="directory-kind">${e.hasSummary?'SOURCE SUMMARY':e.sources.some(s=>s.url)?'SOURCE ARTICLE':'REGISTRY RECORD'}</span><h3>${esc(e.name)} <span aria-hidden="true">↗</span></h3><p>${e.excerpt?esc(e.excerpt.slice(0,145))+(e.excerpt.length>145?'…':''):e.aliases.length?'Also called: '+esc(e.aliases.slice(0,2).join('; ')):'Open the record to see available source information and coverage.'}</p><small>${esc([...new Set(e.sources.map(s=>s.name))].join(' · '))}</small></button>`}
function distance(a,b){if(Math.abs(a.length-b.length)>2)return 9;let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next}return row[b.length]}
function didYouMean(q){q=fold(q);if(q.length<4||q.length>32)return [];return directorySearch.filter(x=>Math.abs(x.title.length-q.length)<=2).map(x=>({name:x.entry.name,d:distance(q,x.title)})).filter(x=>x.d>0&&x.d<=2).sort((a,b)=>a.d-b.d).slice(0,5).map(x=>x.name)}
let suggestTimer;function liveDirectorySuggest(q){clearTimeout(suggestTimer);suggestTimer=setTimeout(()=>{const box=$('#directory-suggest');if(!box)return;let terms=fold(q);let hits=terms.length>1?directorySearch.filter(x=>x.title.startsWith(terms)||x.aliases.some(a=>a===terms)).slice(0,5).map(x=>x.entry.name):[];if(!hits.length)hits=didYouMean(q);box.innerHTML=hits.map(n=>`<button class="chip" type="button" data-suggestion="${esc(n)}">${esc(n)}</button>`).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>dirSearch(b.dataset.suggestion))},180)}
const previousLibrary=library;
library=function(q=''){if(q!==dirState.q){dirState.q=q;dirState.page=0}const all=directoryResults(q),pageSize=24,pages=Math.max(1,Math.ceil(all.length/pageSize));dirState.page=Math.min(dirState.page,pages-1);const shown=all.slice(dirState.page*pageSize,(dirState.page+1)*pageSize),suggestions=all.length?[]:didYouMean(q),m=MEDICAL_DIRECTORY.meta;return `${title('THE CONDITION & HEALTH LIBRARY','A broader path to understanding.','Search common conditions, genetic disorders, rare diseases, symptoms and medical reference topics.')}<div class="coverage-strip"><div><b>${m.entryCount.toLocaleString()}</b><span>indexed source entries</span></div><div><b>${m.summaryCount.toLocaleString()}</b><span>entries with readable summaries</span></div><div><b>${m.resourceCount.toLocaleString()}</b><span>curated resource links</span></div><a href="#coverage">What is covered? ↗</a></div><form class="searchbox directory-search" onsubmit="event.preventDefault();dirSearch(this.q.value)"><input name="q" value="${esc(q)}" aria-label="Search medical directory" placeholder="Condition, symptom, abbreviation or everyday wording…" oninput="liveDirectorySuggest(this.value)" autocomplete="off"><button class="primary">Search</button></form><div id="directory-suggest" class="suggestions" aria-live="polite"></div><div class="directory-filters"><label>Body system or topic<select onchange="dirFilter('group',this.value)"><option value="">All categories</option>${dirGroups.map(g=>`<option ${dirState.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label>Source collection<select onchange="dirFilter('kind',this.value)"><option value="">All collections</option><option value="summary" ${dirState.kind==='summary'?'selected':''}>Readable summaries</option>${Object.entries(dirLabels).map(([k,v])=>`<option value="${k}" ${dirState.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="secondary" onclick="dirState={q:'',group:'',kind:'',letter:'',page:0};dirSearch('')">Clear filters</button></div><div class="alphabet" aria-label="Browse alphabetically">${['All','#',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(l=>`<button aria-pressed="${dirState.letter===(l==='All'?'':l)}" onclick="dirFilter('letter','${l==='All'?'':l}')">${l}</button>`).join('')}</div><div class="sectionhead"><p class="sub">${all.length.toLocaleString()} matching entries${q?' for “'+esc(q)+'”':''}. Search relevance is not diagnostic likelihood.</p><a href="#coverage">Sources & dates</a></div>${shown.length?`<div class="condition-grid directory-grid">${shown.map(directoryCard).join('')}</div>`:`<div class="card"><h2>No entry matches these filters.</h2><p>Try a shorter name, an alternative spelling, or clear the category filter. Missing results do not rule out a condition.</p>${suggestions.length?'<p>Did you mean:</p><div class="suggestions">'+suggestions.map(n=>`<button class="chip" data-correction="${esc(n)}">${esc(n)}</button>`).join('')+'</div>':''}<a href="https://medlineplus.gov/" target="_blank" rel="noopener">Search MedlinePlus ↗</a> · <a href="https://rarediseases.info.nih.gov/" target="_blank" rel="noopener">Search GARD ↗</a></div>`}<div class="directory-pagination"><button class="secondary" ${dirState.page===0?'disabled':''} onclick="dirState.page--;render();window.scrollTo(0,0)">← Previous</button><span>Page ${dirState.page+1} of ${pages}</span><button class="secondary" ${dirState.page>=pages-1?'disabled':''} onclick="dirState.page++;render();window.scrollTo(0,0)">Next →</button></div><p class="fine">${m.mergePolicy} This is broad source coverage, not a claim to include every medical condition. Original content is attributed to its publisher; inclusion does not imply endorsement of Prognos.</p>`};
function loadDirectoryDetails(){if(dirDetails||dirLoading)return;dirLoading=true;dirError='';fetch('directory-details.json').then(r=>{if(!r.ok)throw Error('The source summaries could not be downloaded.');return r.json()}).then(d=>{dirDetails=d;dirLoading=false;if(location.hash.includes('topic-'))render()}).catch(e=>{dirLoading=false;dirError=e.message;if(location.hash.includes('topic-'))render()})}
function textParagraphs(t){return t.split(/\n\s*\n/).filter(Boolean).map(p=>p.trim().endsWith('?')&&p.trim().length<150?`<h3>${esc(p.trim())}</h3>`:`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}
function resourceList(rs){const grouped={};rs.forEach(r=>(grouped[r.category]??=[]).push(r));return Object.entries(grouped).map(([cat,items])=>`<section class="card resource-group"><h2>${esc(cat)}</h2>${items.map(r=>`<div class="resource-item"><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a><p>${esc(r.organization)}${r.credentials?' · '+esc(r.credentials):''}</p></div>`).join('')}</section>`).join('')}
function relatedPrognosGuide(e){return DATA.conditions.find(c=>[c.name,names[c.id]].some(n=>fold(n)===fold(e.name))||e.aliases.some(a=>fold(a)===fold(c.name)||fold(a)===fold(names[c.id])))}
function directoryArticle(id,treatments=false){const e=directoryById.get(id);if(!e)return library();if(!dirDetails&&!dirError)loadDirectoryDetails();const d=dirDetails?.[id],m=MEDICAL_DIRECTORY.meta,guide=relatedPrognosGuide(e);const active=treatments?'treatments':dirTab;const tabs=[['overview','Overview'],['diagnosis','Symptoms & diagnosis'],['research','Research & resources'],['sources','Sources & credibility']];let content='';
if(active==='sources')content=e.sources.map(directorySource).join('')+`<div class="notice">Imported ${m.retrieved}. Import date is not a clinical review date. Text is reproduced from the indicated source exports; Prognos has not independently reviewed it. Different source entries can overlap in scope. <a href="#coverage">Read the coverage details.</a></div>`;
else if(!d)content=`<div class="card" role="status">${dirError?esc(dirError)+` <button class="secondary" onclick="dirError='';loadDirectoryDetails();render()">Retry</button>`:'Loading source summaries and resource links…'}<p>You can still open the original source below.</p></div>`+e.sources.map(directorySource).join('');
else if(active==='overview')content=(d.summaries.length?d.summaries.map(s=>`<section class="card readable"><span class="eyebrow">${esc(s.source.name)} · SOURCE TEXT</span><h2 style="margin-top:10px">Understanding ${esc(e.name)}</h2>${textParagraphs(simple?(s.text.split(/\n\s*\n/).find(p=>p.trim().length>80)||s.text):s.text)}${s.sections.map(x=>`<h3>${esc(x.title)}</h3>${textParagraphs(x.text)}`).join('')}${directorySource(s.source)}</section>`).join(''):`<section class="card"><h2>${e.sources.some(s=>s.url)?'Detailed information is available at the source.':'This condition is indexed, but no patient summary was supplied.'}</h2><p>${e.sources.some(s=>s.url)?'Use the original source links below for the condition description, diagnosis information, review dates and any available treatment information. This record is a source reference, not a full Prognos guide.':'The NIH list includes this disease name, but does not provide a disease page or patient summary for this record. Prognos has not invented a description or treatment. The record remains searchable so a rare diagnosis is not silently excluded.'}</p>${e.sources.map(directorySource).join('')}<a class="link" href="https://rarediseases.info.nih.gov/contact" target="_blank" rel="noopener">Ask a GARD information specialist ↗</a></section>`)+`${guide?`<div class="notice"><a href="#condition/${guide.id}">Open the complementary Prognos plain-language guide →</a></div>`:''}`;
else {const cats=active==='treatments'?['Treatments and Therapies','Living With','Prevention and Risk Factors']:active==='diagnosis'?['Symptoms','Diagnosis and Tests','Start Here','Patient Handouts','Encyclopedia']:null;const rs=d.resources.filter(r=>!cats||cats.includes(r.category));content=`<div class="notice">${active==='treatments'?'These publisher resources describe treatment options; they are not personalized recommendations. Read the original medicine information for side effects, contraindications and interactions. Prognos has not authored a treatment or natural-remedy guide for every directory entry.':active==='diagnosis'?'Source-linked information for discussing symptoms and clinical investigation. Search matches and body location cannot establish a diagnosis.':'Research and support links curated in the source dataset. Individual papers and trial listings are not treatment recommendations.'}</div>${rs.length?resourceList(rs):`<section class="card"><h2>No separate ${active==='treatments'?'treatment':active==='diagnosis'?'diagnostic':'research'} resources were supplied.</h2><p>Check the original source for available information. An empty section does not mean no treatment or research exists.</p>${e.sources.map(directorySource).join('')}</section>`}${active==='treatments'&&guide?`<div class="tools"><a class="primary" href="#medicines/${guide.id}">Prognos medicine-class guide & side effects →</a></div>`:''}`}
return `<div class="article directory-article"><a class="link" href="#library/${encodeURIComponent(dirState.q)}">← Medical library</a>${title(treatments?'STANDARD TREATMENT RESOURCES':'SOURCE-BACKED MEDICAL INFORMATION',esc(e.name),e.hasSummary?'Read published patient information and follow the original sources.':'A clearly labeled source-directory entry.')}<div class="chips">${e.kinds.map(k=>`<span class="chip">${dirLabels[k]}</span>`).join('')}</div>${e.aliases.length?`<details class="alias-list"><summary>Also called · ${e.aliases.length} alternative names</summary><p>${esc(e.aliases.join(' · '))}</p></details>`:''}<div class="tools"><button class="secondary" onclick="speak()">◖ Listen</button><button class="secondary" onclick="simple=!simple;render()">${simple?'Full source summary':'Short overview'}</button><button class="secondary" onclick="saveCondition('${id}')">${saved.includes(id)?'✓ Saved':'Save entry'}</button><button class="secondary" onclick="window.print()">Print</button></div><div class="directory-tabs">${tabs.map(([key,label])=>`<button aria-pressed="${active===key}" onclick="dirTab='${key}';location.hash='condition/${id}';render()">${label}</button>`).join('')}<a class="${active==='treatments'?'selected':''}" href="#medicines/${id}">Standard treatments →</a></div><div class="stack">${content}</div><p class="fine">Educational information; not a diagnosis or prescription. <a href="#emergency">Severe or sudden symptoms? Get urgent help.</a></p></div>`}
const oldArticle=article;article=function(id){return directoryById.has(id)?directoryArticle(id):oldArticle(id)};
const oldMedicines=medicines;medicines=function(id){if(directoryById.has(id))return directoryArticle(id,true);if(id)return oldMedicines(id);return `${title('MEDICINE MATRIX','Treatment information, connected to your condition.','Find a condition first, then open its Standard treatments section for source-linked resources.')}<form class="searchbox" onsubmit="event.preventDefault();dirSearch(this.q.value)"><input name="q" required aria-label="Find treatment information by condition" placeholder="Search any condition in the medical library…"><button class="primary">Find condition →</button></form><div class="notice">The expanded directory includes ${MEDICAL_DIRECTORY.meta.resourceCount.toLocaleString()} curated resource links, including treatment and therapy resources where supplied. The six Prognos medicine-class guides below are still a small authored collection—not the full treatment coverage of the library.</div><div class="sectionhead"><h2>Prognos medicine-class guides</h2><a href="#library">Browse all source entries →</a></div>${conditionCards(DATA.conditions)}<p class="fine">No medicine class or supportive measure is suitable for every patient. Read the original source for adverse effects and discuss suitability with a clinician or pharmacist.</p>`};
