const oldRegion=region;region=function(r){oldRegion(r);const target=$('#region-result');if(!target)return;const groups={Head:['Brain and Nerves','Ear, Nose and Throat','Eyes and Vision'],Chest:['Blood, Heart and Circulation','Lungs and Breathing'],Abdomen:['Digestive System'],Pelvis:['Female Reproductive System','Male Reproductive System','Kidneys and Urinary System'],Arms:['Bones, Joints and Muscles'],Legs:['Bones, Joints and Muscles','Blood, Heart and Circulation']}[r]||[];let available=groups.filter(g=>dirGroups.includes(g));target.innerHTML+=`<div class="notice"><b>Explore the expanded medical library</b><p>The cards above are the original introductory guides, not all possible causes. Browse the full source directory for broader coverage.</p><div class="chips">${available.map(g=>`<button class="chip" data-body-group="${g}">${g} →</button>`).join('')}<a class="link" href="#library">All ${MEDICAL_DIRECTORY.meta.entryCount.toLocaleString()} entries →</a></div></div>`;target.querySelectorAll('[data-body-group]').forEach(b=>b.onclick=()=>{dirState.group=b.dataset.bodyGroup;dirSearch('')})};
const oldHome=home;home=function(){return oldHome().replace('View condition library →',`Browse ${MEDICAL_DIRECTORY.meta.entryCount.toLocaleString()} source entries →`).replace('Understand the conditions that can be harder to put a name to.','Start with a Prognos guide, or search the full medical source library above.')} ;
const oldMission=mission;mission=function(){return oldMission().replace('This first edition contains six condition guides. It is not a comprehensive medical reference.',`The library now indexes ${MEDICAL_DIRECTORY.meta.entryCount.toLocaleString()} source entries, with ${MEDICAL_DIRECTORY.meta.summaryCount.toLocaleString()} readable source summaries and six complementary Prognos guides. Coverage is broad, but no claim of every known disease is made. <a href="#coverage">Inspect coverage and limitations.</a>`)};
function coverage(){const m=MEDICAL_DIRECTORY.meta;return `${title('COVERAGE & SOURCE TRANSPARENCY','Breadth you can inspect.','More information should come with more clarity about where it comes from.')}<div class="coverage-strip"><div><b>${m.entryCount.toLocaleString()}</b><span>directory entries</span></div><div><b>${m.summaryCount.toLocaleString()}</b><span>entries with source summaries</span></div><div><b>${m.resourceCount.toLocaleString()}</b><span>curated resource links</span></div></div><div class="stack"><section class="card"><h2>What is included</h2><p><b>${m.sourceCounts.healthTopics.toLocaleString()} MedlinePlus health topics:</b> the complete English health-topic export dated ${esc(m.medlineSnapshot)}, including condition descriptions, symptoms, tests and wellness subjects.</p><p><b>${m.sourceCounts.geneticSummaries.toLocaleString()} genetic-condition summaries:</b> the full condition-summary collection in the MedlinePlus Genetics export retrieved ${m.retrieved}. Original review and publication dates are preserved.</p><p><b>${m.sourceCounts.gardRecords.toLocaleString()} GARD rare-disease records:</b> the September 2026 NIH list, including names and aliases. ${m.withDiseasePage.toLocaleString()} records supply disease-page URLs; others have no supplied patient page. Registry records alone are not clinical summaries.</p><p><b>${m.encyclopediaArticleCount.toLocaleString()} encyclopedia article links:</b> clinical articles referenced by MedlinePlus topics. Article text is read at the source; it has not been copied into Prognos.</p><p>${m.mergePolicy}</p></section><section class="card"><h2>What “comprehensive” does and does not mean here</h2><p>This expansion covers the complete records in the listed source exports. It is not an exhaustive list of every known medical condition, and source coverage varies by disease. Rare conditions may have little published patient information.</p><p>Readable summaries, linked original articles and registry-only records are visibly labeled. Six original Prognos guides retain their plain-language and medicine-class information. The larger directory does not imply a custom treatment guide, side-effect list or specialist recommendation for every entry.</p><p>Imported text retains its source wording. A short overview is an excerpt, not an AI simplification. Prognos has not independently clinically reviewed these materials, and source organizations do not endorse this app.</p></section><section class="card"><h2>Provenance & update policy</h2><p>This is a dated snapshot, imported ${m.retrieved}, not a live medical feed. Open the source to check for newer guidance. The reproducible import script can rebuild the library from new official exports; automatic updates are not enabled.</p><div class="resource-item"><a href="https://medlineplus.gov/xml.html" target="_blank" rel="noopener">MedlinePlus downloadable health-topic data ↗</a></div><div class="resource-item"><a href="https://medlineplus.gov/about/developers/geneticsdatafilesapi/" target="_blank" rel="noopener">MedlinePlus Genetics data and API ↗</a></div><div class="resource-item"><a href="https://rarediseases.info.nih.gov/about" target="_blank" rel="noopener">GARD methodology and downloadable disease list ↗</a></div><div class="resource-item"><a href="https://medlineplus.gov/about/using/usingcontent/" target="_blank" rel="noopener">MedlinePlus content attribution and use ↗</a></div></section></div>`}
const oldAsk=ask;ask=function(q){if(/appointment|doctor visit|prepare|chest pain|can't breathe|cannot breathe|suicid|stroke|worst headache|severe pain|overdose/i.test(q))return oldAsk(q);if(!q.trim())return;chat.push({role:'user',html:esc(q)});const savedState={...dirState};dirState={q:'',kind:'',group:'',letter:'',page:0};const results=directoryResults(q).slice(0,5);dirState=savedState;chat.push({role:'assistant',html:results.length?`These are source-directory matches, not a diagnosis or personalized AI advice. Open an entry to inspect its source, coverage and available information.<div class="directory-chat">${results.map(e=>`<p><a href="#condition/${e.id}"><b>${esc(e.name)}</b> →</a><br>${e.hasSummary?'Source summary available':'Source-directory record'} · ${esc(e.sources[0].name)}</p>`).join('')}</div>`:'No clear match was found. Try the condition name or a shorter symptom phrase in the expanded library. No match does not rule out illness. <a href="#library">Open the medical directory →</a>'});render();$('#messages')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'})};
